// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 rollTo) public {
        vm.assume(caller != address(0));
        rollTo = bound(rollTo, 1, type(uint64).max);

        vm.deal(caller, 20 ether);

        vm.warp(block.timestamp + 1);
        vm.roll(uint256(rollTo));

        vm.startPrank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        vm.stopPrank();

        bool shouldBeZero = (block.number % 15 == 0);
        assertTrue((address(c).balance == 0) == shouldBeZero);
    }
}
